mapper.select:
select 

from ASSET_PLAN_DETAIL
where ASSET_PLAN_CODE = #{assetPlanCode,jdbcType=VARCHAR}
  and ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

mapper.delete:
delete from ASSET_PLAN_DETAIL
where ASSET_PLAN_CODE = #{assetPlanCode,jdbcType=VARCHAR}
  and ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

mapper.update:
update ASSET_PLAN_DETAIL
set PLAN_INIT_AMT = #{planInitAmt,jdbcType=DECIMAL},
    PLAN_CHANGE_AMT = #{planChangeAmt,jdbcType=DECIMAL},
    PLAN_TARGET_AMT = #{planTargetAmt,jdbcType=DECIMAL},
